import nodemailer from "nodemailer";
import { appBaseUrl, emailConfigured } from "./config";
import type { Invoice, Reminder } from "./types";
import { formatMoney } from "./format";

export function mailStatus() {
  return {
    configured: emailConfigured(),
    from: process.env.SMTP_FROM || null,
  };
}

function transporter() {
  if (!emailConfigured()) return null;
  return nodemailer.createTransport({
    host: process.env.SMTP_HOST,
    port: Number(process.env.SMTP_PORT || 587),
    secure: process.env.SMTP_SECURE === "true",
    auth: {
      user: process.env.SMTP_USER,
      pass: process.env.SMTP_PASS,
    },
  });
}

export async function sendPaymentReminderEmail(
  invoice: Invoice,
  reminder: Reminder,
): Promise<{ sent: boolean; error?: string }> {
  const to = invoice.partyEmail?.trim();
  if (!to) {
    return { sent: false, error: "No party email on invoice" };
  }

  const transport = transporter();
  if (!transport) {
    return { sent: false, error: "SMTP not configured" };
  }

  const payUrl = `${appBaseUrl()}/pay/${invoice.id}`;
  const amount = formatMoney(invoice.amount, invoice.currency);
  const subject =
    reminder.kind === "overdue"
      ? `Overdue invoice — ${amount} still unpaid`
      : reminder.kind === "due_today"
        ? `Payment due today — ${amount}`
        : `Payment reminder — ${amount} due ${invoice.dueDate}`;

  const html = `
  <div style="font-family:Georgia,serif;max-width:560px;margin:0 auto;color:#14221c;line-height:1.5">
    <p style="font-size:13px;letter-spacing:0.12em;text-transform:uppercase;color:#3f6b55">Remitra</p>
    <h1 style="font-size:22px;margin:8px 0 16px">Payment reminder</h1>
    <p>${reminder.message}</p>
    <p style="margin:20px 0;padding:16px;background:#eef4ef;border-radius:12px">
      <strong>${invoice.partyName}</strong><br/>
      Amount: <strong>${amount}</strong><br/>
      Due: ${invoice.dueDate}<br/>
      ${invoice.description ? `Note: ${invoice.description}<br/>` : ""}
    </p>
    ${
      invoice.direction === "receivable"
        ? `<p><a href="${payUrl}" style="display:inline-block;background:#1a6b5c;color:#fff;text-decoration:none;padding:12px 20px;border-radius:999px;font-weight:600">Pay invoice / open QR</a></p>
           <p style="font-size:13px;color:#3d5248">Or scan the QR on that page and submit your payment ID after paying.</p>`
        : `<p style="font-size:13px;color:#3d5248">This is a payable reminder for your own records.</p>`
    }
    <p style="font-size:12px;color:#3d5248;margin-top:28px">Sent automatically by Remitra.</p>
  </div>`;

  try {
    await transport.sendMail({
      from: process.env.SMTP_FROM,
      to,
      subject,
      text: `${reminder.message}\n\nAmount: ${amount}\nDue: ${invoice.dueDate}\nPay: ${payUrl}`,
      html,
    });
    return { sent: true };
  } catch (err) {
    console.error("Email send failed:", err);
    return {
      sent: false,
      error: err instanceof Error ? err.message : "Email failed",
    };
  }
}
